-- Every US tax-exempt organization -- 1.97 million nonprofits with EIN, type, and finances.
-- Auto-generated by scripts/gen_evidence_pages.py: 1,974,830 rows > 100k, so this is a BOUNDED pre-aggregate (parquet-safe by construction), not select *.
-- top categories by STATE; LIMIT keeps the parquet bounded.
select "STATE" as category, count(*) as records
from THE_LIBRARY.COMPANIES.NONPROFIT_ORGANIZATIONS
group by 1
order by 2 desc
limit 200
